class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        segments = []
        start = 1
        k = 1
        while start <= 10**9:
            end = min(4**k - 1, 10**9)
            segments.append((start, end, k))
            start = 4**k
            k += 1
            if start > 10**9:
                break

        total_ops = 0
        for l, r in queries:
            current_divisions = 0
            for seg_start, seg_end, k in segments:
                low = max(seg_start, l)
                high = min(seg_end, r)
                if low <= high:
                    count = high - low + 1
                    current_divisions += k * count
            total_ops += current_divisions // 2

        return total_ops

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        def perimeter_dist(x, y):
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            else:  # x == 0
                return 3 * side + (side - y)

        sorted_points = sorted(points, key=lambda p: perimeter_dist(p[0], p[1]))

        def can_select(d):
            count = 0
            last_x, last_y = -1, -1
            for x, y in sorted_points:
                if count == 0:
                    last_x, last_y = x, y
                    count += 1
                    if count == k:
                        return True
                else:
                    dist = abs(x - last_x) + abs(y - last_y)
                    if dist >= d:
                        last_x, last_y = x, y
                        count += 1
                        if count == k:
                            return True
            return count >= k

        low, high = 1, 2 * side
        ans = 1
        while low <= high:
            mid = (low + high) // 2
            if can_select(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

