class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        total_ops = 0
        for t in target:
            min_ops = float('inf')
            for n in nums:
                remainder = n % t
                ops = (t - remainder) % t
                if ops < min_ops:
                    min_ops = ops
            total_ops += min_ops
        return total_ops

