class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        def kadane(arr):
            if not arr:
                return float('-inf')
            max_ending_here = arr[0]
            max_so_far = arr[0]
            for i in range(1, len(arr)):
                max_ending_here = max(arr[i], max_ending_here + arr[i])
                max_so_far = max(max_so_far, max_ending_here)
            return max_so_far

        # Base case: no operation
        max_sum = kadane(nums)

        # Get unique elements
        unique_elements = list(set(nums))

        for x in unique_elements:
            # Create a new array without all occurrences of x
            filtered = [num for num in nums if num != x]
            if not filtered:
                continue
            current_max = kadane(filtered)
            if current_max > max_sum:
                max_sum = current_max

        return max_sum

import sys
from itertools import combinations

def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        K = int(next(iterator))
        A = []
        for _ in range(N):
            A.append(int(next(iterator)))
    except StopIteration:
        return

    # Since the problem guarantees that binomial(N, K) <= 10^6,
    # we can safely iterate over all combinations.
    # The maximum number of combinations is 1,000,000, which is feasible.

    max_xor = 0

    # Generate all combinations of K elements and compute their XOR
    for combo in combinations(A, K):
        current_xor = 0
        for val in combo:
            current_xor ^= val

        if current_xor > max_xor:
            max_xor = current_xor

    print(max_xor)

if __name__ == '__main__':
    solve()
